CREATE OR REPLACE FUNCTION public.admin_find_users(_search text) RETURNS TABLE(id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT p.id FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE lower(u.email)=lower(_search) OR p.full_name ILIKE '%' || replace(replace(_search,'%',''), '_','') || '%' OR p.id::text=_search LIMIT 500 $$;
REVOKE ALL ON FUNCTION public.admin_find_users(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_find_users(text) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_upsert_record(_actor uuid,_table text,_id text,_data jsonb,_delete boolean,_reason text) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.admin_save_record(_actor,_table,nullif(_id,''),_data,_delete,_reason) $$;
REVOKE ALL ON FUNCTION public.admin_upsert_record(uuid,text,text,jsonb,boolean,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.admin_upsert_record(uuid,text,text,jsonb,boolean,text) TO service_role;